{
  "page": {
    "use": "page/basic",
    "data": {
      "title": "Rental memberships",
      "site": "Rentals",
      "description": "Compare the Day Pass, Weekender and Season Pass rental plans.",
      "heading": "Pricing: rental memberships"
    },
    "slots": {
      "main": [
        {
          "use": "content/section",
          "key": "plans",
          "data": { "title": "Rental plans" },
          "slots": {
            "body": [
              {
                "use": "content/section",
                "key": "day-pass",
                "data": { "title": "Day Pass" },
                "slots": {
                  "body": [
                    { "use": "content/prose", "key": "details", "data": { "html": "<p>$0 a month</p><ul><li>Pay per rental</li><li>Members get 20% off</li></ul>" } },
                    { "use": "action/link-button", "key": "cta", "data": { "label": "Rent now", "href": "#" } }
                  ]
                }
              },
              {
                "use": "content/section",
                "key": "weekender",
                "data": { "title": "Weekender" },
                "slots": {
                  "body": [
                    { "use": "content/prose", "key": "details", "data": { "html": "<p>Most popular</p><p>$19 a month</p><ul><li>2 rentals a month included</li><li>Free gear delivery</li></ul>" } },
                    { "use": "action/link-button", "key": "cta", "data": { "label": "Choose Weekender", "href": "#" } }
                  ]
                }
              },
              {
                "use": "content/section",
                "key": "season-pass",
                "data": { "title": "Season Pass" },
                "slots": {
                  "body": [
                    { "use": "content/prose", "key": "details", "data": { "html": "<p>$49 a month</p><ul><li>Unlimited rentals</li><li>Priority booking for kayaks</li><li>Free delivery</li></ul>" } },
                    { "use": "action/link-button", "key": "cta", "data": { "label": "Choose Season Pass", "href": "#" } }
                  ]
                }
              }
            ]
          }
        },
        {
          "use": "content/section",
          "key": "comparison",
          "data": { "title": "Compare features" },
          "slots": {
            "body": [
              {
                "use": "data/table",
                "key": "features",
                "data": {
                  "caption": "Features by plan",
                  "columns": ["Day Pass", "Weekender", "Season Pass"],
                  "rows": [
                    { "header": "Included rentals", "cells": ["None", "2 per month", "Unlimited"] },
                    { "header": "Member discount", "cells": ["20%", "20%", "20%"] },
                    { "header": "Free delivery", "cells": ["No", "Yes", "Yes"] },
                    { "header": "Priority kayak booking", "cells": ["No", "No", "Yes"] }
                  ]
                }
              },
              { "use": "content/prose", "key": "note", "data": { "html": "<p>Prices include tax. Cancel any time.</p>" } }
            ]
          }
        }
      ]
    }
  }
}

